use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs = input.as_array().unwrap();
    let mut indices = Vec::new();
    let mut quantum = input.as_i64().unwrap();

    for (index, job) in jobs.iter().enumerate() {
        if job.is_positive() {
            indices.push(index);
            quantum -= job;
        }
    }

    indices.sort_unstable();
    indices.into_iter().map(|index| serde_json::Value::from(index)).collect()
}

fn main() {
    let input = serde_json::Value::from("{\"input\":{\"jobs\":[3,1,2],"quantum":2}}");
    let expected = serde_json::Value::from(vec![1, 2, 0]));
    assert_eq!(solve(input), expected);
}
